function renderRooms() {
  const list = $("room-list");
  if (list) {
    const loose = state.rooms.filter((r) => !r.projectId);
    list.innerHTML = loose.length
      ? loose.map(roomRow).join("")
      : `<li class="empty muted">${T("app_rooms_loose_none")}</li>`;
  }
  renderRoomsPanel();
  renderOverview();
}

async function shareProject(project) {
  const sub = (name) => fb.collection(db, "users", state.uid, "projects", project.id, name);
  const [estSnap, shopSnap] = await Promise.all([
    fb.getDocs(sub("estimations")),
    fb.getDocs(sub("shoppingItems")),
  ]);

  const alive = (snap, limit) => {
    const rows = [];
    snap.forEach((d) => { if (!d.data().deletedAt && rows.length < limit) rows.push(d.data()); });
    return rows;
  };
  const estimations = alive(estSnap, 200);
  const shoppingItems = alive(shopSnap, 500);
  const currencyCode = (estimations[0] && estimations[0].currencyCode) || "PLN";

  const token = shareToken();
  const now = Date.now();
  await fb.setDoc(fb.doc(db, "sharedProjects", token), {
    ownerId: state.uid,
    schemaVersion: SCHEMA_VERSION,
    createdAt: now,
    refreshedAt: now,
    projectName: project.name,
    currencyCode,
    estimations,
    shoppingItems,

    creatorLevel: state.level,
  });
  return `${location.origin}/p/${token}`;
}

function wireWorkspace() {
  $("project-form").addEventListener("submit", async (e) => {
    e.preventDefault();
    const input = $("project-name");
    const name = input.value.trim().slice(0, 120);
    if (!name) return;
    input.value = "";
    try { await addProject(name); } catch (err) { status(T("app_err_unknown"), true); }
  });

  $("project-list").addEventListener("submit", async (e) => {
    const form = e.target.closest("[data-room-form]");
    if (!form) return;
    e.preventDefault();
    const li = form.closest("li[data-id]");
    const get = (f) => form.querySelector(`[data-f="${f}"]`).value;
    const name = get("name").trim().slice(0, 120);
    if (!name || !li) return;

    const l = Math.min(num(get("lengthM")), 1000);
    const w = Math.min(num(get("widthM")), 1000);
    const h = Math.min(num(get("heightM")), 100);
    try {
      await addRoom(name, l, w, h, li.dataset.id);
    } catch (err) { status(T("app_err_unknown"), true); }
  });

  $("project-list").addEventListener("click", async (e) => {
    const li = e.target.closest("li[data-id]");
    if (!li) return;
    const project = state.projects.find((p) => p.id === li.dataset.id);

    const roomLi = e.target.closest(".app-rooms li[data-id]");
    if (roomLi && e.target.closest("[data-del]")) {
      const room = state.rooms.find((r) => r.id === roomLi.dataset.id);
      if (room) await deleteRoom(room);
      return;
    }
    if (!project) return;

    if (e.target.closest("[data-del]")) {
      await tombstone(projectDoc(project.id), project, { name: project.name, archived: !!project.archived });
    } else if (e.target.closest("[data-share]")) {
      try {
        const url = await shareProject(project);
        await navigator.clipboard.writeText(url).catch(() => {});
        status(`${T("app_share_copied")}: ${url}`);
      } catch (err) {
        status(T("app_err_unknown"), true);
      }
    }
  });

  $("room-list").addEventListener("click", async (e) => {
    const li = e.target.closest("li[data-id]");
    if (!li || !e.target.closest("[data-del]")) return;
    const room = state.rooms.find((r) => r.id === li.dataset.id);
    if (room) await deleteRoom(room);
  });
}

const deleteRoom = (room) => tombstone(roomDoc(room.id), room, {
  name: room.name, lengthM: room.lengthM, widthM: room.widthM, heightM: room.heightM,
});

function proLink(routeId, id) {
  const lang = document.documentElement.lang || "pl";
  const nav = window.LM_NAV && window.LM_NAV[routeId];
  const base = (nav && (nav[lang] || nav.pl)) || `/${routeId}/`;
  return `${base}?id=${encodeURIComponent(id)}`;
}

function fmtDay(day) {
  if (!day) return "";
  const d = new Date(`${day}T00:00:00`);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString(document.documentElement.lang || "pl", { day: "numeric", month: "short" });
}

function renderOverview() {
  const stats = $("overview-stats");
  if (stats) {
    const activeProjects = state.projects.filter((p) => !p.archived);
    const sched = typeof crmSchedule === "function" ? crmSchedule() : null;
    const dueSoon = sched ? sched.counts.late + sched.counts.today + sched.counts.soon : 0;
    const clientsCount = typeof crmClients === "function" ? crmClients().length : 0;
    stats.innerHTML = `
      <div class="app-stat-card"><div class="lbl">${T("app_stat_projects")}</div><div class="val">${activeProjects.length}</div></div>
      <div class="app-stat-card"><div class="lbl">${T("app_stat_clients")}</div><div class="val">${clientsCount}</div></div>
      <div class="app-stat-card"><div class="lbl">${T("app_stat_schedule")}</div><div class="val">${dueSoon}</div></div>
      <div class="app-stat-card"><div class="lbl">${T("app_rooms_title")}</div><div class="val">${state.rooms.length}</div></div>`;
  }

  const projList = $("overview-projects");
  if (projList) {
    const top = state.projects.filter((p) => !p.archived).slice(0, 5);
    projList.innerHTML = top.length
      ? top.map((p) => `<li><span class="row-name">${escapeHtml(p.name)}</span></li>`).join("")
      : `<li class="empty muted">${T("app_empty_projects")}</li>`;
  }

  const schedList = $("overview-schedule");
  if (schedList) {
    const sched = typeof crmSchedule === "function" ? crmSchedule() : null;
    const items = sched ? [...sched.buckets.late, ...sched.buckets.today, ...sched.buckets.soon].slice(0, 5) : [];
    schedList.innerHTML = items.length
      ? items.map((j) => `<li><span class="row-name">${escapeHtml(j.name)}<em class="muted"> — ${fmtDay(j.dueDate)}</em></span></li>`).join("")
      : `<li class="empty muted">${T("app_schedule_empty_day")}</li>`;
  }

  const matList = $("overview-materials");
  if (matList) {
    const mats = typeof omMaterials === "function" ? omMaterials().slice(0, 5) : [];
    matList.innerHTML = mats.length
      ? mats.map((m) => `<li><span class="row-name">${escapeHtml(m.name)}</span></li>`).join("")
      : `<li class="empty muted">${T("app_materials_empty")}</li>`;
  }
}

