const calState = { year: 0, month: 0, day: "", adding: false, picking: false };

function calCells(year, month) {
  const first = new Date(year, month, 1);
  const offset = (first.getDay() + 6) % 7;
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const totalCells = Math.ceil((offset + daysInMonth) / 7) * 7;
  const cells = [];
  for (let i = 0; i < totalCells; i++) cells.push(new Date(year, month, 1 - offset + i));
  return cells;
}

const dayKey = (d) => {
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};

function calJobColor(value) {
  if (typeof crmJobColor === "function") return crmJobColor(value);
  if (typeof JOB_COLORS !== "undefined" && Array.isArray(JOB_COLORS)) {
    return JOB_COLORS.indexOf(value) >= 0 ? value : "";
  }
  return "";
}

function renderCalDayPanel() {
  const box = $("acctcal-daypanel");
  if (!box) return;
  const lang = document.documentElement.lang || "pl";
  const day = calState.day;
  const d = new Date(`${day}T00:00:00`);
  const label = isNaN(d.getTime()) ? day
    : d.toLocaleDateString(lang, { weekday: "long", day: "numeric", month: "long" });
  const byDay = typeof crmJobsByDay === "function" ? crmJobsByDay() : {};
  const jobs = byDay[day] || [];
  const slots = jobs.map((j) => {
    const client = j.clientId && typeof crmClient === "function" ? crmClient(j.clientId) : null;
    const color = calJobColor(j.color);
    const colorClass = color ? ` cal-slot-${color}` : "";
    const clientName = client ? `${escapeHtml(client.name)} — ` : "";
    return `<div class="cal-slot${colorClass}"><div>
        <div class="t">${escapeHtml(j.name)}</div>
        <div class="d">${clientName}${T("job_st_" + j.status)}</div>
      </div></div>`;
  }).join("");

  const clients = typeof crmClients === "function" ? crmClients() : [];
  const clientOptions = [`<option value="">${T("cal_add_noclient")}</option>`]
    .concat(clients.map((c) => `<option value="${escapeHtml(c.id)}">${escapeHtml(c.name)}</option>`))
    .join("");

  const colors = typeof JOB_COLORS !== "undefined" && Array.isArray(JOB_COLORS) ? JOB_COLORS : [];
  const colorOptions = [`<option value="">${T("job_color_none")}</option>`]
    .concat(colors.map((token) => `<option value="${escapeHtml(token)}">${T("job_color_" + token)}</option>`))
    .join("");

  box.innerHTML = `<h3>${escapeHtml(label)}</h3>` +
    (jobs.length ? slots : `<p class="muted">${T("app_schedule_empty_day")}</p>`) +
    `<p><button type="button" class="btn btn-ghost btn-sm" id="acctcal-add-toggle">${T("app_cal_add")}</button></p>
    <form id="acctcal-add-form" class="cal-add"${calState.adding ? "" : " hidden"}>
      <p class="ws-mat-grid">
        <label class="ws-mat-f">
          <span class="ws-bar-label">${T("job_new")}</span>
          <input type="text" id="acctcal-add-name" maxlength="120" required>
        </label>
        <label class="ws-mat-f">
          <span class="ws-bar-label">${T("cal_add_date")}</span>
          <input type="date" id="acctcal-add-date" value="${escapeHtml(calState.day || "")}" required>
        </label>
        <label class="ws-mat-f">
          <span class="ws-bar-label">${T("job_client")}</span>
          <select id="acctcal-add-client">${clientOptions}</select>
        </label>
        <label class="ws-mat-f">
          <span class="ws-bar-label">${T("job_color")}</span>
          <select id="acctcal-add-color">${colorOptions}</select>
        </label>
        <label class="ws-mat-f">
          <span class="ws-bar-label">${T("job_desc")}</span>
          <input type="text" id="acctcal-add-desc" maxlength="2000">
        </label>
      </p>
      <p>
        <button type="submit" class="btn btn-primary btn-sm">${T("cal_add_btn")}</button>
        <button type="button" id="acctcal-add-cancel" class="btn btn-ghost btn-sm">${T("app_cancel")}</button>
      </p>
    </form>`;
}

function renderSchedule() {
  const grid = $("acctcal-grid");
  if (!grid) return;
  const today = typeof crmToday === "function" ? crmToday() : dayKey(new Date());
  if (!calState.year) {
    const now = new Date();
    calState.year = now.getFullYear();
    calState.month = now.getMonth();
    calState.day = today;
  }
  const lang = document.documentElement.lang || "pl";
  const monthEl = $("acctcal-month");
  if (monthEl) {
    if (!calState.picking) {
      const label = new Date(calState.year, calState.month, 1)
        .toLocaleDateString(lang, { month: "long", year: "numeric" });
      monthEl.innerHTML = `<button type="button" id="acctcal-month-toggle" class="cal-month-btn" aria-expanded="false">${escapeHtml(label)}<span class="cal-month-caret" aria-hidden="true">▾</span></button>`;
    } else {
      const monthOptions = Array.from({ length: 12 }, (_, i) => {
        const name = new Date(calState.year, i, 1).toLocaleDateString(lang, { month: "long" });
        return `<option value="${i}"${i === calState.month ? " selected" : ""}>${escapeHtml(name)}</option>`;
      }).join("");
      const yearOptions = Array.from({ length: 11 }, (_, i) => {
        const y = calState.year - 5 + i;
        return `<option value="${y}"${y === calState.year ? " selected" : ""}>${y}</option>`;
      }).join("");
      monthEl.innerHTML = `<span class="cal-month-pick"><select id="acctcal-pick-month" aria-label="${escapeHtml(T("app_cal_month"))}">${monthOptions}</select><select id="acctcal-pick-year" aria-label="${escapeHtml(T("app_cal_year"))}">${yearOptions}</select></span>`;
    }
  }

  const wk = $("acctcal-weekdays");
  if (wk) {
    const monday = new Date(2026, 0, 5);
    wk.innerHTML = Array.from({ length: 7 }, (_, i) => {
      const d = new Date(monday.getFullYear(), monday.getMonth(), monday.getDate() + i);
      return `<span>${escapeHtml(d.toLocaleDateString(lang, { weekday: "short" }))}</span>`;
    }).join("");
  }

  const byDay = typeof crmJobsByDay === "function" ? crmJobsByDay() : {};
  const openStatus = typeof JOB_OPEN_STATUS !== "undefined" ? JOB_OPEN_STATUS : [];
  grid.innerHTML = calCells(calState.year, calState.month).map((d) => {
    const key = dayKey(d);
    const out = d.getMonth() !== calState.month;
    const jobs = byDay[key] || [];
    const shown = jobs.slice(0, 2).map((j) => {
      const done = openStatus.indexOf(j.status) === -1;
      const late = !done && key < today;
      const color = calJobColor(j.color);
      const colorClass = color ? ` cal-ev-${color}` : "";
      return `<span class="cal-ev${done ? " done" : late ? " late" : ""}${colorClass}">${escapeHtml(j.name)}</span>`;
    }).join("");
    const more = jobs.length > 2 ? `<span class="cal-ev more">+${jobs.length - 2}</span>` : "";
    return `<button type="button" class="cal-day${out ? " is-out" : ""}${key === today ? " is-today" : ""}${key === calState.day ? " is-selected" : ""}" data-day="${key}">
        <span class="num">${d.getDate()}</span>${shown}${more}
      </button>`;
  }).join("");

  renderCalDayPanel();
}

function wireSchedulePanel() {
  const grid = $("acctcal-grid");
  if (!grid) return;
  grid.addEventListener("click", (e) => {
    const btn = e.target.closest("[data-day]");
    if (!btn) return;
    calState.picking = false;
    calState.day = btn.dataset.day;
    renderSchedule();
  });

  $("acctcal-prev").addEventListener("click", () => {
    calState.picking = false;
    calState.month -= 1;
    if (calState.month < 0) { calState.month = 11; calState.year -= 1; }
    calState.day = dayKey(new Date(calState.year, calState.month, 1));
    renderSchedule();
  });
  $("acctcal-next").addEventListener("click", () => {
    calState.picking = false;
    calState.month += 1;
    if (calState.month > 11) { calState.month = 0; calState.year += 1; }
    calState.day = dayKey(new Date(calState.year, calState.month, 1));
    renderSchedule();
  });
  $("acctcal-today").addEventListener("click", () => {
    calState.picking = false;
    calState.year = 0;
    renderSchedule();
  });

  const tool = $("acctcal-tool");
  if (tool) {
    tool.addEventListener("click", (e) => {
      if (e.target.closest("#acctcal-month-toggle")) {
        calState.picking = true;
        renderSchedule();
        return;
      }
      if (calState.picking && !e.target.closest("#acctcal-month")) {
        calState.picking = false;
        renderSchedule();
      }
    });
    tool.addEventListener("change", (e) => {
      if (e.target.id === "acctcal-pick-month") {
        calState.month = Number(e.target.value);
        calState.picking = false;
        calState.day = dayKey(new Date(calState.year, calState.month, 1));
        renderSchedule();
      } else if (e.target.id === "acctcal-pick-year") {
        calState.year = Number(e.target.value);
        calState.picking = false;
        calState.day = dayKey(new Date(calState.year, calState.month, 1));
        renderSchedule();
      }
    });
  }

  const panel = $("acctcal-daypanel");
  if (!panel) return;
  panel.addEventListener("click", (e) => {
    if (e.target.closest("#acctcal-add-toggle")) {
      calState.adding = true;
      renderCalDayPanel();
    } else if (e.target.closest("#acctcal-add-cancel")) {
      calState.adding = false;
      renderCalDayPanel();
    }
  });
  panel.addEventListener("submit", (e) => {
    const form = e.target.closest("#acctcal-add-form");
    if (!form) return;
    e.preventDefault();
    const nameInput = form.querySelector("#acctcal-add-name");
    const dateInput = form.querySelector("#acctcal-add-date");
    const clientSelect = form.querySelector("#acctcal-add-client");
    const colorSelect = form.querySelector("#acctcal-add-color");
    const descInput = form.querySelector("#acctcal-add-desc");
    const name = (nameInput ? nameInput.value : "").trim();
    const dueDate = (dateInput ? dateInput.value : "").trim();
    const clientId = (clientSelect ? clientSelect.value : "").trim();
    const color = (colorSelect ? colorSelect.value : "").trim();
    const description = (descInput ? descInput.value : "").trim();
    if (!name || !dueDate || typeof crmAddJob !== "function") return;
    const row = crmAddJob({ name, dueDate, clientId, color, description });
    if (!row) return;
    calState.adding = false;
    calState.day = dueDate;
    const d = new Date(`${dueDate}T00:00:00`);
    if (!isNaN(d.getTime())) {
      calState.year = d.getFullYear();
      calState.month = d.getMonth();
    }
    renderSchedule();
  });
}

const canCosts = () => typeof lmCan === "function" && lmCan("costs", state.level);

function renderMaterialsPanel() {
  const list = $("acctmat-list");
  if (!list || typeof omMaterials !== "function") return;
  const rows = omMaterials();

  const priced = canCosts();
  list.innerHTML = rows.length ? rows.map((m) => `<li data-id="${escapeHtml(m.id)}">
      <span class="row-name">${escapeHtml(m.name)}${priced && m.priceMinor != null && typeof wsMoney === "function" ? ` <em class="muted">${wsMoney(m.priceMinor, m.currencyCode)}</em>` : ""}</span>
      <span class="row-actions">
        <button type="button" class="btn btn-ghost btn-sm" data-del>${T("app_delete")}</button>
      </span>
    </li>`).join("") : `<li class="empty muted">${T("app_materials_empty")}</li>`;
}

function wireMaterialsPanel() {
  const list = $("acctmat-list");
  if (!list) return;
  list.addEventListener("click", (e) => {
    const li = e.target.closest("li[data-id]");
    if (!li || !e.target.closest("[data-del]") || typeof omDelete !== "function") return;
    omDelete(li.dataset.id);
    renderMaterialsPanel();
    renderOverview();
  });
}

function renderRoomsPanel() {
  const box = $("acctrooms-list");
  if (!box) return;
  const byProject = {};
  const loose = [];
  state.rooms.forEach((r) => {
    if (r.projectId) (byProject[r.projectId] || (byProject[r.projectId] = [])).push(r);
    else loose.push(r);
  });
  const groups = state.projects
    .filter((p) => byProject[p.id] && byProject[p.id].length)
    .map((p) => `<div class="app-card"><h3>${escapeHtml(p.name)}</h3>
        <ul class="data-list">${byProject[p.id].map(roomRow).join("")}</ul></div>`);
  if (loose.length) {
    groups.push(`<div class="app-card"><h3>${T("app_rooms_no_project")}</h3>
        <ul class="data-list">${loose.map(roomRow).join("")}</ul></div>`);
  }
  box.innerHTML = groups.length ? groups.join("") : `<p class="muted">${T("app_rooms_empty")}</p>`;
}

function wireRoomsPanel() {
  const box = $("acctrooms-list");
  if (!box) return;
  box.addEventListener("click", async (e) => {
    const li = e.target.closest("li[data-id]");
    if (!li || !e.target.closest("[data-del]")) return;
    const room = state.rooms.find((r) => r.id === li.dataset.id);
    if (room) { await deleteRoom(room); renderRoomsPanel(); }
  });
}

const SYNC_ACCOUNT_KEY = "liczmat-sync-account";

function syncAccount() {
  try { return localStorage.getItem(SYNC_ACCOUNT_KEY) || ""; } catch (e) { return ""; }
}

function setSyncAccount(uid) {
  try {
    if (uid) localStorage.setItem(SYNC_ACCOUNT_KEY, uid);
    else localStorage.removeItem(SYNC_ACCOUNT_KEY);
  } catch (e) {}
}

function localCounts() {
  const local = typeof wsExport === "function" ? wsExport() : null;
  if (!local) return null;
  const alive = (rows) => (rows || []).filter((r) => !r.deletedAt).length;
  const pro = typeof crmExport === "function" ? crmExport() : null;
  return {
    projects: alive(local.projects), rooms: alive(local.rooms),
    estimations: alive(local.estimations), shoppingItems: alive(local.shoppingItems),
    clients: alive(pro && pro.clients), jobs: alive(pro && pro.jobs),
    quotes: alive(pro && pro.quotes),
  };
}

function foreignWorkspace() {
  const stamp = syncAccount();
  if (!stamp || !state.uid || stamp === state.uid) return false;
  const counts = localCounts();
  if (!counts) return false;

  return counts.projects + counts.rooms + counts.estimations + counts.shoppingItems
    + counts.clients + counts.jobs + counts.quotes > 0;
}

function renderLocalSummary() {
  const box = $("app-sync-local");
  const counts = localCounts();
  if (!box || !counts) return;
  box.textContent = `${T("app_sync_local")}: ${counts.projects} × ${T("app_projects")}, ` +
    `${counts.rooms} × ${T("app_rooms")}, ${counts.estimations} × ${T("ws_lines")}, ` +
    `${counts.shoppingItems} × ${T("proj_mat_t")}`;

  const foreign = foreignWorkspace();
  const warning = $("app-sync-foreign");
  if (warning) {
    warning.textContent = foreign ? T("app_sync_foreign") : "";
    warning.hidden = !foreign;
  }
  ["app-sync-push", "app-sync-pull"].forEach((id) => {
    const button = $(id);
    if (button) button.disabled = foreign;
  });
}

function mirrorToLocal(incoming) {
  if (syncBusy !== 0 || foreignWorkspace() || typeof wsImport !== "function") return;
  syncBusy++;
  try {
    wsImport(incoming);
  } finally {
    syncBusy--;
  }
  renderLocalSummary();
}

async function syncPushAll(since) {
  if (typeof wsExport !== "function") return;

  const MERGE = { merge: true };
  const local = wsExport();
  const skippable = (row) => Number.isFinite(since) && Number.isFinite(row.updatedAt) && row.updatedAt <= since;
  for (const p of local.projects) {
    if (!pathId(p.id)) continue;
    if (skippable(p)) continue;
    await fb.setDoc(projectDoc(p.id), {
      name: String(p.name).slice(0, 120),
      archived: !!p.archived,
      ...syncFields(p.createdAt, p.deletedAt),
    }, MERGE);
  }
  for (const r of local.rooms) {
    if (!pathId(r.id)) continue;
    if (skippable(r)) continue;

    await fb.setDoc(roomDoc(r.id), {
      name: String(r.name).slice(0, 120),
      lengthM: num(r.lengthM), widthM: num(r.widthM), heightM: num(r.heightM),
      projectId: r.projectId || null,
      ...syncFields(r.createdAt, r.deletedAt),
    }, MERGE);
  }
  for (const e of local.estimations) {

    const projectSeg = pathId(e.projectId), lineSeg = pathId(e.id);
    if (!projectSeg || !lineSeg) continue;
    if (skippable(e)) continue;
    const ref = fb.doc(db, "users", state.uid, "projects", projectSeg, "estimations", lineSeg);
    await fb.setDoc(ref, {
      name: String(e.name).slice(0, 120),
      calculationType: e.calculationType,
      materialCategory: e.materialCategory,
      requiredUnits: Math.round(e.requiredUnits) || 0,
      unitLabel: String(e.unitLabel).slice(0, 24),
      totalCostMinor: Math.round(e.totalCostMinor) || 0,
      wastePercentage: Number(e.wastePercentage) || 0,
      wasteCostMinor: Math.round(e.wasteCostMinor) || 0,
      currencyCode: String(e.currencyCode).slice(0, 3),
      inputJson: String(e.inputJson || "{}").slice(0, 20000),
      ...syncFields(e.createdAt, e.deletedAt),
    }, MERGE);
  }
  for (const s of local.shoppingItems) {

    const projectSeg = pathId(s.projectId), itemSeg = pathId(s.id);
    if (!projectSeg || !itemSeg) continue;
    if (skippable(s)) continue;
    const ref = fb.doc(db, "users", state.uid, "projects", projectSeg, "shoppingItems", itemSeg);
    await fb.setDoc(ref, {
      estimationId: s.estimationId ? String(s.estimationId).slice(0, 64) : null,
      name: String(s.name).slice(0, 120),
      materialCategory: String(s.materialCategory || "OTHER").slice(0, 40),
      quantity: Math.max(0, num(s.quantity)),
      unit: String(s.unit || "").slice(0, 24),
      estimatedCostMinor: Math.round(s.estimatedCostMinor) || 0,
      currencyCode: String(s.currencyCode || "PLN").slice(0, 3),
      isPurchased: !!s.isPurchased,

      note: String(s.note || "").slice(0, 500),
      ...syncFields(s.createdAt, s.deletedAt),
    }, MERGE);
  }
  await pushProWorkspace(since);

  await pushOwnMaterials(since);
}

async function syncPullAll() {
  const incoming = await downloadAccount();

  const landed = [wsImport(incoming)];

  if (typeof crmImport === "function") landed.push(crmImport(incoming));

  if (typeof omImport === "function") landed.push(omImport(incoming));
  return !landed.some((ok) => ok === false);
}

async function autoReconcile() {
  if (foreignWorkspace()) return;
  syncBusy++;
  try {
    await syncPullAll();

    const startedAt = Date.now();
    await syncPushAll();
    lastAutoPushAt = startedAt;
    setSyncAccount(state.uid);
    renderLocalSummary();
  } catch (e) {

  } finally {
    syncBusy--;
  }
}

function wireSyncPanel() {
  const push = $("app-sync-push");
  const pull = $("app-sync-pull");
  if (!push || !pull || typeof wsExport !== "function") return;

  push.addEventListener("click", async () => {

    if (foreignWorkspace()) { status(T("app_sync_foreign"), true); return; }
    push.disabled = true;
    syncBusy++;
    try {
      await syncPushAll();
      setSyncAccount(state.uid);
      renderLocalSummary();
      status(T("app_sync_pushed"));
    } catch (err) {
      status(T("app_err_unknown"), true);
    } finally {
      syncBusy--;
      push.disabled = false;
    }
  });

  pull.addEventListener("click", async () => {
    if (foreignWorkspace()) { status(T("app_sync_foreign"), true); return; }
    pull.disabled = true;
    syncBusy++;
    try {
      const ok = await syncPullAll();
      renderLocalSummary();
      if (!ok) { status(T("ws_save_failed"), true); return; }
      setSyncAccount(state.uid);
      status(T("app_sync_pulled"));
    } catch (err) {
      status(T("app_err_unknown"), true);
    } finally {
      syncBusy--;
      pull.disabled = false;
    }
  });
}

let upSyncTimer = null;

function armUpSync() {
  if (syncBusy !== 0) return;
  if (!state.uid || foreignWorkspace()) return;
  if (upSyncTimer) {
    clearTimeout(upSyncTimer);
    upSyncTimer = null;
  }
  upSyncTimer = setTimeout(async () => {
    upSyncTimer = null;
    if (!state.uid || syncBusy !== 0 || foreignWorkspace()) return;
    const startedAt = Date.now();
    syncBusy++;
    try {
      await syncPushAll(lastAutoPushAt);
      lastAutoPushAt = startedAt;
      setSyncAccount(state.uid);
      renderLocalSummary();
    } catch (e) {

    } finally {
      syncBusy--;
    }
  }, 1500);
}

["workspacechange", "crmchange", "ownmaterialschange"].forEach((name) => {
  document.addEventListener(name, armUpSync);
});

const proDoc = (collection, id) => fb.doc(db, "users", state.uid, collection, id);

function proDay(value) {
  const day = String(value == null ? "" : value).trim();
  return /^\d{4}-\d{2}-\d{2}$/.test(day) ? day : "";
}

async function pushProWorkspace(since) {
  if (typeof crmExport !== "function") return;
  const MERGE = { merge: true };
  const pro = crmExport();
  const text = (value, max) => String(value == null ? "" : value).slice(0, max);

  const jobStatus = (value) => (["new", "active", "done", "cancelled"].indexOf(value) >= 0 ? value : "new");
  const skippable = (row) => Number.isFinite(since) && Number.isFinite(row.updatedAt) && row.updatedAt <= since;

  for (const c of pro.clients || []) {
    const seg = pathId(c.id);
    if (!seg) continue;
    if (skippable(c)) continue;
    await fb.setDoc(proDoc("clients", seg), {
      name: text(c.name, 120),
      phone: text(c.phone, 200),
      email: text(c.email, 200),
      address: text(c.address, 200),
      note: text(c.note, 2000),
      projectIds: (Array.isArray(c.projectIds) ? c.projectIds : [])
        .filter((id) => !!pathId(id)).slice(0, 200),
      archived: !!c.archived,
      ...syncFields(c.createdAt, c.deletedAt),
    }, MERGE);
  }

  for (const j of pro.jobs || []) {
    const seg = pathId(j.id);
    if (!seg) continue;
    if (skippable(j)) continue;
    const value = j.valueMinor == null ? null : Math.round(j.valueMinor);
    await fb.setDoc(proDoc("jobs", seg), {
      name: text(j.name, 120),
      clientId: text(j.clientId, 64),
      projectId: text(j.projectId, 64),
      status: jobStatus(j.status),
      description: text(j.description, 2000),
      note: text(j.note, 2000),
      color: text(j.color, 16),
      dueDate: proDay(j.dueDate),
      valueMinor: value,
      currencyCode: value == null ? "" : text(j.currencyCode, 3),
      ...syncFields(j.createdAt, j.deletedAt),
    }, MERGE);
  }

  for (const q of pro.quotes || []) {
    const seg = pathId(q.id);
    if (!seg) continue;
    if (skippable(q)) continue;
    const labour = (Array.isArray(q.labour) ? q.labour : []).slice(0, 60).map((line) => ({
      id: text(line.id, 64),
      name: text(line.name, 120),

      quantity: line.quantity == null ? null : Math.max(0, num(line.quantity)),
      unit: text(line.unit, 24),
      amountMinor: Math.round(line.amountMinor) || 0,
    }));
    const money = labour.reduce((sum, line) => sum + line.amountMinor, 0);
    await fb.setDoc(proDoc("quotes", seg), {
      name: text(q.name, 120),
      projectId: text(q.projectId, 64),
      labour: labour,
      marginPct: Math.min(1000, Math.max(0, num(q.marginPct))),
      note: text(q.note, 2000),
      currencyCode: money === 0 ? "" : text(q.currencyCode, 3),
      ...syncFields(q.createdAt, q.deletedAt),
    }, MERGE);
  }
}

async function pushOwnMaterials(since) {
  if (typeof omExport !== "function") return;
  const MERGE = { merge: true };
  const store = omExport();
  const text = (value, max) => String(value == null ? "" : value).slice(0, max);

  const measure = (value, max) => {
    if (value === null || value === undefined || value === "") return null;
    const n = Number(value);
    return Number.isFinite(n) && n >= 0 ? Math.min(n, max) : null;
  };
  const skippable = (row) => Number.isFinite(since) && Number.isFinite(row.updatedAt) && row.updatedAt <= since;

  for (const m of store.materials || []) {
    const seg = pathId(m.id);
    if (!seg) continue;
    if (skippable(m)) continue;
    const priceMinor = m.priceMinor == null ? null : Math.round(m.priceMinor);
    const prices = (Array.isArray(m.prices) ? m.prices : [])
      .filter((p) => p && Number.isFinite(Number(p.priceMinor)) && Number.isFinite(Number(p.recordedAt)))
      .sort((a, b) => Number(b.recordedAt) - Number(a.recordedAt))
      .slice(0, 60)
      .map((p) => ({
        priceMinor: Math.round(Number(p.priceMinor)),
        currencyCode: text(p.currencyCode, 3),
        recordedAt: Math.round(Number(p.recordedAt)),
      }));
    await fb.setDoc(proDoc("materials", seg), {
      name: text(m.name, 120),
      category: text(m.category || "OTHER", 40),
      application: text(m.application || "WALL_FLOOR_COVERING", 40),
      widthMm: measure(m.widthMm, 100000),
      lengthMm: measure(m.lengthMm, 100000),
      kerfMm: measure(m.kerfMm, 1000),
      coveragePerUnitM2: measure(m.coveragePerUnitM2, 10000),
      packageAreaM2: measure(m.packageAreaM2, 10000),
      wastePercent: measure(m.wastePercent, 100),
      priceMinor: priceMinor,

      currencyCode: priceMinor == null ? "" : text(m.currencyCode, 3),
      priceUpdatedAt: m.priceUpdatedAt == null ? null : Math.round(m.priceUpdatedAt),
      prices: prices,
      ...syncFields(m.createdAt, m.deletedAt),
    }, MERGE);
  }
}

async function downloadAccount() {
  const out = {
    projects: [], rooms: [], estimations: [], shoppingItems: [],
    clients: [], jobs: [], quotes: [], materials: [],
  };
  const rows = (snap) => { const list = []; snap.forEach((d) => list.push({ id: d.id, ...d.data() })); return list; };

  const projSnap = await fb.getDocs(fb.collection(db, "users", state.uid, "projects"));
  out.projects = rows(projSnap);
  out.rooms = rows(await fb.getDocs(fb.collection(db, "users", state.uid, "rooms")));

  for (const name of ["clients", "jobs", "quotes", "materials"]) {
    try {
      out[name] = rows(await fb.getDocs(fb.collection(db, "users", state.uid, name)));
    } catch (err) {
      out[name] = [];
    }
  }

  for (const project of out.projects) {
    const sub = (name) => fb.collection(db, "users", state.uid, "projects", project.id, name);
    const est = rows(await fb.getDocs(sub("estimations"))).map((e) => ({ ...e, projectId: project.id }));
    const shop = rows(await fb.getDocs(sub("shoppingItems"))).map((s) => ({ ...s, projectId: project.id }));
    out.estimations.push(...est);
    out.shoppingItems.push(...shop);
  }
  return out;
}

async function reauthenticate(password) {
  const user = auth.currentUser;
  if (!user) throw Object.assign(new Error("no user"), { code: "auth/user-not-found" });
  if (hasPasswordProvider(user)) {
    const credential = fb.EmailAuthProvider.credential(user.email, password);
    await fb.reauthenticateWithCredential(user, credential);
  } else {
    await fb.reauthenticateWithPopup(user, new fb.GoogleAuthProvider());
  }
}

function wireAccountPanel() {
  $("app-verify-send").addEventListener("click", async () => {
    try {
      await fb.sendEmailVerification(auth.currentUser);
      status(T("app_verify_sent"));
    } catch (err) { status(authMessage(err && err.code), true); }
  });

  $("email-form").addEventListener("submit", async (e) => {
    e.preventDefault();
    try {
      await reauthenticate($("email-password").value);

      await fb.verifyBeforeUpdateEmail(auth.currentUser, $("email-new").value.trim());
      $("email-password").value = "";
      status(T("app_email_changed"));
    } catch (err) { status(authMessage(err && err.code), true); }
  });

  $("password-form").addEventListener("submit", async (e) => {
    e.preventDefault();
    try {
      await reauthenticate($("password-current").value);
      await fb.updatePassword(auth.currentUser, $("password-new").value);
      $("password-current").value = "";
      $("password-new").value = "";
      status(T("app_password_changed"));
    } catch (err) { status(authMessage(err && err.code), true); }
  });

  const DEVICE_DATA_KEYS = [
    "materio-workspace-v1",
    "materio-active-project",
    "liczmat-recent-calcs",
    "liczmat-crm-v1",
    "liczmat-materials-v1",
    SYNC_ACCOUNT_KEY,
  ];

  $("app-wipe").addEventListener("click", () => {
    if (!confirm(T("app_wipe_confirm"))) return;
    try {
      DEVICE_DATA_KEYS.forEach((key) => localStorage.removeItem(key));
    } catch (e) {
      status(T("app_err_unknown"), true);
      return;
    }

    document.dispatchEvent(new CustomEvent("workspacechange"));
    renderLocalSummary();
    status(T("app_wipe_done"));
  });

  $("app-export").addEventListener("click", async () => {
    try {
      const data = await downloadAccount();
      const blob = new Blob([JSON.stringify({ ...data, exportedAt: Date.now(), uid: state.uid }, null, 2)],
        { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "materio-account.json";
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (err) { status(T("app_err_unknown"), true); }
  });

  $("app-delete-account").addEventListener("click", async () => {
    if (!confirm(T("app_delete_confirm"))) return;
    const button = $("app-delete-account");
    button.disabled = true;
    try {
      await reauthenticate($("delete-password").value);

      stopListening();
      await deleteEverything();
      await fb.deleteUser(auth.currentUser);
      status(T("app_deleted"));
    } catch (err) {
      const code = err && err.code;

      status(code === "permission-denied" ? T("app_err_delete_denied") : authMessage(code), true);

      if (state.uid) {
        listen("projects", (rows) => { state.projects = rows; renderProjects(); });
        listen("rooms", (rows) => { state.rooms = rows; renderRooms(); renderProjects(); });
        listenProfile();
      }
    } finally {
      button.disabled = false;
    }
  });
}

async function deleteEverything() {
  const del = (ref) => fb.deleteDoc(ref);

  await del(fb.doc(db, "users", state.uid));

  const projSnap = await fb.getDocs(fb.collection(db, "users", state.uid, "projects"));
  for (const project of projSnap.docs) {
    for (const name of ["estimations", "shoppingItems"]) {
      const sub = await fb.getDocs(fb.collection(db, "users", state.uid, "projects", project.id, name));
      for (const d of sub.docs) await del(d.ref);
    }
    await del(project.ref);
  }

  const roomSnap = await fb.getDocs(fb.collection(db, "users", state.uid, "rooms"));
  for (const d of roomSnap.docs) await del(d.ref);

  const shared = await fb.getDocs(
    fb.query(fb.collection(db, "sharedProjects"), fb.where("ownerId", "==", state.uid)));
  for (const d of shared.docs) await del(d.ref);
}

document.addEventListener("DOMContentLoaded", () => {
  boot().catch((err) => {

    console.error("LiczMat /app/ did not finish starting:", err);
    status(T("app_err_unknown"), true);
  });
});
